function actionOrder(actions){return [...actions].sort((x,y)=>{if(x.type==='switch'&&y.type!=='switch')return-1;if(y.type==='switch'&&x.type!=='switch')return 1;const px=x.type==='move'?(mv(x.moveId)?.priority||0):0,py=y.type==='move'?(mv(y.moveId)?.priority||0):0;if(px!==py)return py-px;const sx=effectiveSpeed(x.actor),sy=effectiveSpeed(y.actor);if(sx===sy)return Math.random()<.5?-1:1;return state.field.trickRoom>0?sx-sy:sy-sx;});}
