function replaceFaintsAuto(){let needsHuman=[];for(const t of state.trainers){for(let i=0;i<t.active.length;i++){const p=t.active[i];if(p&&p.hp<=0){const options=bench(t);if(!options.length)continue;if(t.controller==='cpu'){const n=bestBench(t);t.active[i]=n;n.position=p.position;entry(n);applyLunarDanceIfPending(n);log(`${t.label}は ${n.name}を繰り出した！`);}else needsHuman.push({trainer:t,slot:i,old:p,options});}}}return needsHuman;}
